import java.lang.annotation.*;
import java.lang.reflect.*;
import java.util.*;

public class MiniContainer {

    @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.FIELD) @interface Inject {}
    @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.METHOD) @interface PostConstruct {}

    interface BeanPostProcessor {
        default Object before(Object bean, String name) { return bean; }
        default Object after(Object bean, String name) { return bean; }
    }

    static class OrderService {
        @Inject PaymentService payments;
        OrderService() { System.out.println("  [instantiate] OrderService"); }
        @PostConstruct void init() { System.out.println("  [@PostConstruct] OrderService"); }
        String place() { return "order placed, " + payments.charge(); }
    }
    static class PaymentService {
        @Inject OrderService orders;   // circular reference
        PaymentService() { System.out.println("  [instantiate] PaymentService"); }
        @PostConstruct void init() { System.out.println("  [@PostConstruct] PaymentService"); }
        String charge() { return "payment charged"; }
}

private final Map<String, Class<?>> definitions = new LinkedHashMap<>();
private final Map<String, Object> singletonObjects = new HashMap<>();       // level 1
private final Map<String, Object> earlySingletonObjects = new HashMap<>();  // level 2
private final Map<String, java.util.function.Supplier<Object>> singletonFactories
    = new HashMap<>();                                                      // level 3
private final Set<String> inCreation = new LinkedHashSet<>();
private final List<BeanPostProcessor> processors = new ArrayList<>();

void register(String name, Class<?> type) { definitions.put(name, type); }

Object getBean(String name) {
    Object o = getSingleton(name);
    return o != null ? o : create(name);
}

private Object getSingleton(String name) {       // DefaultSingletonBeanRegistry.getSingleton
    Object o = singletonObjects.get(name);
    if (o == null && inCreation.contains(name)) {
        o = earlySingletonObjects.get(name);
        if (o == null && singletonFactories.containsKey(name)) {
            o = singletonFactories.remove(name).get();      // promote level 3 -> level 2
            earlySingletonObjects.put(name, o);
            System.out.println("  [cache] early reference for '" + name
                + "' promoted from level 3 to level 2");
        }
    }
    return o;
}

private Object create(String name) {             // doCreateBean in the Spring factory
    System.out.println("create '" + name + "'");
    inCreation.add(name);
    try {
        Class<?> type = definitions.get(name);
        Object raw = type.getDeclaredConstructor().newInstance();
        singletonFactories.put(name, () -> raw);             // addSingletonFactory
        for (Field f : type.getDeclaredFields()) {            // populateBean
            if (f.isAnnotationPresent(Inject.class)) {
                String dep = definitions.entrySet().stream()
                    .filter(e -> f.getType().isAssignableFrom(e.getValue()))
                    .findFirst().orElseThrow().getKey();
                System.out.println("  [inject] " + name + "." + f.getName()
                    + " <- '" + dep + "'");
                f.setAccessible(true);
                f.set(raw, getBean(dep));
            }
        }
        Object bean = raw;                                    // initializeBean
        for (BeanPostProcessor p : processors) bean = p.before(bean, name);
        for (Method m : type.getDeclaredMethods())
            if (m.isAnnotationPresent(PostConstruct.class)) {
                m.setAccessible(true);
                m.invoke(raw);
            }
        for (BeanPostProcessor p : processors) bean = p.after(bean, name);
        singletonObjects.put(name, bean);
        singletonFactories.remove(name);
        earlySingletonObjects.remove(name);
        return bean;
    } catch (ReflectiveOperationException e) {
        throw new IllegalStateException(e);
    } finally {
        inCreation.remove(name);
    }
}

public static void main(String[] args) {
    MiniContainer ctx = new MiniContainer();
    ctx.processors.add(new BeanPostProcessor() {
        public Object before(Object b, String n) {
            System.out.println("  [BPP.before] " + n);
            return b;
        }
            public Object after(Object b, String n) {
                System.out.println("  [BPP.after]  " + n);
                return b;
            }
        });
        ctx.register("orderService", OrderService.class);
        ctx.register("paymentService", PaymentService.class);
        OrderService os = (OrderService) ctx.getBean("orderService");
        System.out.println(os.place());
        System.out.println("same instance: " + (os.payments.orders == os));
    }
}

