@Configuration(proxyBeanMethods = false)
public class LifecycleProbe {

    @Bean
    static BeanFactoryPostProcessor definitionLogger() {            // static: runs very early
        return (ConfigurableListableBeanFactory bf) ->
            System.out.println("BFPP   definitions=" + bf.getBeanDefinitionCount()
                + " probe.scope=" + bf.getBeanDefinition("probe").getScope());
    }

    @Bean
    static BeanPostProcessor stepLogger() {
        return new BeanPostProcessor() {
            @Override
            public Object postProcessBeforeInitialization(Object bean, String name)
                    throws BeansException {
                if (name.equals("probe")) System.out.println("BPP    before-init");
                return bean;
            }
            @Override
            public Object postProcessAfterInitialization(Object bean, String name)
                    throws BeansException {
                if (name.equals("probe")) System.out.println("BPP    after-init");
                return bean;
            }
        };
    }

    @Bean(initMethod = "customInit", destroyMethod = "customDestroy")
    Probe probe() {
        return new Probe();
    }

    public static class Probe implements BeanNameAware, ApplicationContextAware,
                                         InitializingBean, DisposableBean {
        public Probe() { System.out.println("1 constructor"); }
        @Override public void setBeanName(String n) { System.out.println("2 BeanNameAware " + n); }
        @Override public void setApplicationContext(ApplicationContext c) {
            System.out.println("3 ApplicationContextAware"); }
        @PostConstruct void postConstruct() { System.out.println("4 @PostConstruct"); }
        @Override public void afterPropertiesSet() { System.out.println("5 afterPropertiesSet"); }
        void customInit() { System.out.println("6 initMethod"); }
        @PreDestroy void preDestroy() { System.out.println("7 @PreDestroy"); }
        @Override public void destroy() { System.out.println("8 DisposableBean.destroy"); }
        void customDestroy() { System.out.println("9 destroyMethod"); }
    }
}

