package com.example.library.aop;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;

@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.METHOD)
public @interface Timed {
    /** Name of the metric or log label; defaults to the method name. */
    String value() default "";
}

package com.example.library.aop;

import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.annotation.Around;
import org.aspectj.lang.annotation.Aspect;
import org.aspectj.lang.annotation.Pointcut;
import org.aspectj.lang.reflect.MethodSignature;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;

@Aspect
@Component
@Order(2)
public class TimingAspect {

    private static final Logger log = LoggerFactory.getLogger(TimingAspect.class);

    @Pointcut("within(com.example.library..*Service)")
    void serviceLayer() { }

    @Around("serviceLayer() && @annotation(timed)")
    public Object time(ProceedingJoinPoint pjp, Timed timed) throws Throwable {
        MethodSignature sig = (MethodSignature) pjp.getSignature();
        String label = timed.value().isEmpty() ? sig.getName() : timed.value();
        long start = System.nanoTime();
        try {
            return pjp.proceed();                       // the return value must be passed on
        } finally {
            long ms = (System.nanoTime() - start) / 1_000_000;
            log.info("{} took {} ms on thread {}", label, ms, Thread.currentThread().getName());
        }
    }
}

package com.example.library.aop;

import org.aspectj.lang.JoinPoint;
import org.aspectj.lang.annotation.AfterReturning;
import org.aspectj.lang.annotation.AfterThrowing;
import org.aspectj.lang.annotation.Aspect;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;

@Aspect
@Component
@Order(1)                                   // outermost: wraps TimingAspect
public class AuditAspect {
    private static final Logger log = LoggerFactory.getLogger(AuditAspect.class);

    @AfterReturning(pointcut = "@annotation(com.example.library.aop.Timed)", returning = "result")
    public void ok(JoinPoint jp, Object result) {
        log.info("audit ok: {} -> {}", jp.getSignature().toShortString(), result);
    }

    @AfterThrowing(pointcut = "@annotation(com.example.library.aop.Timed)", throwing = "ex")
    public void failed(JoinPoint jp, Exception ex) {
        log.warn("audit failed: {} -> {}", jp.getSignature().toShortString(), ex.toString());
    }
}

