import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.List;

public class SelfInvocation {

    interface AccountService {
        void transfer(String from, String to);
        void audit(String message);
    }

    static class AccountServiceImpl implements AccountService {
        @Override public void transfer(String from, String to) {
            System.out.println("    transfer " + from + " -> " + to);
            audit("transfer done");           // this.audit(...): bypasses the proxy
        }
        @Override public void audit(String message) {
            System.out.println("    audit: " + message);
        }
    }

    static class TxHandler implements InvocationHandler {
        private final Object target;
        private final String order;
        TxHandler(Object target, String order) { this.target = target; this.order = order; }
        @Override public Object invoke(Object proxy, Method m, Object[] args) throws Throwable {
            System.out.println("  [" + order + "] before " + m.getName());
            try {
                return m.invoke(target, args);
            } finally {
                System.out.println("  [" + order + "] after  " + m.getName());
            }
        }
    }

    static AccountService wrap(AccountService target, String order) {
        return (AccountService) Proxy.newProxyInstance(
            AccountService.class.getClassLoader(), new Class<?>[] {AccountService.class},
            new TxHandler(target, order));
    }

    public static void main(String[] args) {
        AccountService target = new AccountServiceImpl();

        System.out.println("1. call through one proxy:");
        AccountService proxy = wrap(target, "tx");
        proxy.transfer("A", "B");

        System.out.println("2. chain of two proxies (outer = first advice):");
        AccountService chained = wrap(wrap(target, "inner"), "outer");
        chained.audit("direct call");

        System.out.println("3. proxy class facts:");
        System.out.println("  class = " + proxy.getClass().getName());
        System.out.println("  is subclass of impl? " + (proxy instanceof AccountServiceImpl));
        System.out.println("  interfaces = " + List.of(proxy.getClass().getInterfaces()));
    }
}

public class FinalMethodProxy {

    static class ReportService {
        private final String owner;
        ReportService(String owner) { this.owner = owner; }
        public String open()  { return "open by " + owner; }          // overridable
        public final String close() { return "close by " + owner; }   // final: cannot be overridden
    }

    /** A CGLIB proxy amounts to a subclass that forwards overridable methods to the target. */
    static class ReportServiceProxy extends ReportService {
        private final ReportService target;
        ReportServiceProxy(ReportService target) {
            super(null);                       // proxy instance has no state of its own
            this.target = target;
        }
        @Override public String open() {
            System.out.println("  [advice] before open");
            return target.open();
        }
    }

    public static void main(String[] args) {
        ReportService real = new ReportService("alice");
        ReportService proxy = new ReportServiceProxy(real);
        System.out.println("open():  " + proxy.open());
        System.out.println("close(): " + proxy.close());
    }
}

