import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

public class RelaxedBinding {

    /** Canonical form: lower-case, kebab-case, dot-separated (as in the Spring Boot reference). */
    static String canonical(String name) {
        StringBuilder sb = new StringBuilder();
        for (char c : name.toCharArray()) {
            if (c == '_') sb.append('-');                  // underscore notation
            else if (Character.isUpperCase(c)) sb.append('-').append(Character.toLowerCase(c));
            else sb.append(c);
        }
        return sb.toString();
    }

    /** Environment variable form: dots to underscores, dashes removed, upper case. */
    static String toEnvVar(String canonical) {
        return canonical.replace('.', '_').replace("-", "").toUpperCase(Locale.ROOT);
    }

    record Source(String name, Map<String, String> values) {}

    static String resolve(String key, List<Source> sourcesByPrecedence) {
        for (Source s : sourcesByPrecedence) {
            String v = s.values().get(key);
            if (v != null) {
                System.out.printf("  %-24s -> %-8s (from %s)%n", key, v, s.name());
                return v;
            }
        }
        System.out.printf("  %-24s -> <unbound>%n", key);
        return null;
    }

    public static void main(String[] args) {
        System.out.println("Spellings of one property and its canonical form:");
        for (String s : List.of("app.max-retries", "app.maxRetries", "app.max_retries"))
            System.out.printf("  %-18s -> %s%n", s, canonical(s));
        System.out.println("Environment variable for app.max-retries: "
            + toEnvVar("app.max-retries"));

        Map<String, String> cmd = new LinkedHashMap<>(Map.of("app.timeout", "1s"));
        Map<String, String> env = new LinkedHashMap<>(
            Map.of("app.timeout", "2s", "app.pool-size", "20"));
        Map<String, String> profileYaml = new LinkedHashMap<>(
            Map.of("app.timeout", "3s", "app.region", "eu"));
        Map<String, String> baseYaml = new LinkedHashMap<>(
            Map.of("app.timeout", "9s", "app.region", "us",
            "app.pool-size", "5", "app.name", "orders"));
        List<Source> sources = List.of(new Source("command line", cmd),
            new Source("environment", env), new Source("application-prod.yml", profileYaml),
            new Source("application.yml", baseYaml));
        System.out.println("Resolution, highest precedence first:");
        for (String k : List.of("app.timeout", "app.pool-size", "app.region", "app.name",
                                "app.missing"))
            resolve(k, sources);
    }
}

