/**
 * Configuration of the audit starter.
 *
 * @param enabled whether audit logging is active
 * @param prefix text placed in front of every audit line
 * @param slowThreshold operations slower than this are logged at WARN
 */
@ConfigurationProperties(prefix = "audit")
@Validated
public record AuditProperties(
        @DefaultValue("true") boolean enabled,
        @DefaultValue("AUDIT") @NotBlank String prefix,
        @DefaultValue("500ms") Duration slowThreshold) {
}

package com.example.audit;
import java.time.Duration;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
public class AuditLogger {
    private static final Logger log = LoggerFactory.getLogger(AuditLogger.class);
    private final String prefix;
    private final Duration slowThreshold;
    public AuditLogger(String prefix, Duration slowThreshold) {
        this.prefix = prefix;
        this.slowThreshold = slowThreshold;
    }

    public String prefix() {
        return prefix;
    }

    public void record(String event, Duration took) {
        if (took.compareTo(slowThreshold) > 0) {
            log.warn("{} slow event={} took={}ms", prefix, event, took.toMillis());
        } else {
            log.info("{} event={} took={}ms", prefix, event, took.toMillis());
        }
    }
}

