import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;

@AutoConfiguration
@ConditionalOnClass(AuditLogger.class)
@ConditionalOnProperty(prefix = "audit", name = "enabled", havingValue = "true",
        matchIfMissing = true)
@EnableConfigurationProperties(AuditProperties.class)
public class AuditAutoConfiguration {

    @Bean
    @ConditionalOnMissingBean            // backs off when the application defines its own
    AuditLogger auditLogger(AuditProperties properties) {
        return new AuditLogger(properties.prefix(), properties.slowThreshold());
    }
}

package com.example.audit;

import static org.assertj.core.api.Assertions.assertThat;

import java.time.Duration;
import org.junit.jupiter.api.Test;
import org.springframework.boot.autoconfigure.AutoConfigurations;
import org.springframework.boot.test.context.runner.ApplicationContextRunner;

class AuditAutoConfigurationTest {

    private final ApplicationContextRunner runner = new ApplicationContextRunner()
            .withConfiguration(AutoConfigurations.of(AuditAutoConfiguration.class));

    @Test
    void createsLoggerWithDefaults() {
        runner.run(ctx -> assertThat(ctx).hasSingleBean(AuditLogger.class));
    }

    @Test
    void bindsProperties() {
        runner.withPropertyValues("audit.prefix=SEC", "audit.slow-threshold=2s")
              .run(ctx -> assertThat(ctx.getBean(AuditLogger.class).prefix()).isEqualTo("SEC"));
    }
    @Test
    void backsOffWhenApplicationDefinesBean() {
        runner.withBean(AuditLogger.class, () -> new AuditLogger("CUSTOM", Duration.ZERO))
              .run(ctx -> assertThat(ctx.getBean(AuditLogger.class).prefix()).isEqualTo("CUSTOM"));
    }

    @Test
    void disabledByProperty() {
        runner.withPropertyValues("audit.enabled=false")
              .run(ctx -> assertThat(ctx).doesNotHaveBean(AuditLogger.class));
    }

    @Test
    void blankPrefixFailsStartup() {
        runner.withPropertyValues("audit.prefix= ")
              .run(ctx -> assertThat(ctx).hasFailed());
    }
}

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Predicate;
import java.util.function.Supplier;

public class MiniAutoConfig {

    record Ctx(Map<String, Object> beans, Map<String, String> props) {
        boolean hasBeanOfType(Class<?> t) {
            return beans.values().stream().anyMatch(t::isInstance);
        }
    }

    record Condition(String description, Predicate<Ctx> test) {}

    record Candidate(String beanName, List<Condition> conditions, Supplier<Object> factory) {}

    static Condition onClass(String className) {
        return new Condition("@ConditionalOnClass(" + className + ")", c -> {
            try {
                Class.forName(className);
                return true;
            } catch (ClassNotFoundException e) {
                return false;
            }
        });
    }
    static Condition onProperty(String key, String expected) {
        return new Condition("@ConditionalOnProperty(" + key + "=" + expected + ")",
            c -> expected.equals(c.props().get(key)));
    }
    static Condition onMissingBean(Class<?> type) {
        return new Condition("@ConditionalOnMissingBean(" + type.getSimpleName() + ")",
            c -> !c.hasBeanOfType(type));
    }

    interface Clock2 { String now(); }
    record SystemClock2() implements Clock2 { public String now() { return "system"; } }
    record FixedClock2() implements Clock2 { public String now() { return "fixed"; } }
    record MetricsRegistry(String backend) {}

    public static void main(String[] args) {
        Ctx ctx = new Ctx(new LinkedHashMap<>(), new LinkedHashMap<>());
        ctx.props().put("app.metrics.enabled", "true");

        // 1. user configuration is processed first
        ctx.beans().put("userClock", new FixedClock2());

        // 2. auto-configuration candidates (the order of the imports file), evaluated afterwards
        List<Candidate> imports = List.of(
            new Candidate("systemClock", List.of(onMissingBean(Clock2.class)), SystemClock2::new),
            new Candidate("prometheusRegistry", List.of(
                onClass("io.prometheus.client.CollectorRegistry"),
                onProperty("app.metrics.enabled", "true")),
                () -> new MetricsRegistry("prometheus")),
            new Candidate("simpleRegistry", List.of(
                onClass("java.util.concurrent.ConcurrentHashMap"),
                onProperty("app.metrics.enabled", "true"),
                onMissingBean(MetricsRegistry.class)), () -> new MetricsRegistry("simple")),
            new Candidate("debugEndpoint", List.of(onProperty("app.debug", "true")),
                () -> "endpoint"));

        List<String> positive = new ArrayList<>();
        List<String> negative = new ArrayList<>();
        for (Candidate c : imports) {
            Condition failed = c.conditions().stream()
                .filter(k -> !k.test().test(ctx)).findFirst().orElse(null);
            if (failed == null) {
                ctx.beans().put(c.beanName(), c.factory().get());
                positive.add(c.beanName());
            } else {
                negative.add(c.beanName() + ": did not match, " + failed.description());
            }
        }
        System.out.println("Positive matches: " + positive);
        System.out.println("Negative matches:");
        negative.forEach(n -> System.out.println("  " + n));
        System.out.println("Beans: " + ctx.beans());
    }
}

