package com.example.library.book;

import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageImpl;
import org.springframework.data.domain.Pageable;
import org.springframework.data.domain.Sort;
import org.springframework.stereotype.Service;

@Service
public class BookService {

    private static final List<String> SORTABLE = List.of("title", "author", "year");

    private final Map<Long, BookDto> store = new ConcurrentHashMap<>();
    private final AtomicLong ids = new AtomicLong();

    public Page<BookDto> page(Pageable pageable) {
        Comparator<BookDto> order = Comparator.comparing(BookDto::title);
        Sort.Order requested = pageable.getSort().stream().findFirst().orElse(null);
        if (requested != null) {
            if (!SORTABLE.contains(requested.getProperty())) {
                throw new IllegalArgumentException("Unsupported sort property: "
                        + requested.getProperty());
            }
            order = switch (requested.getProperty()) {
                case "author" -> Comparator.comparing(BookDto::author);
                case "year" -> Comparator.comparingInt(BookDto::year);
                default -> Comparator.comparing(BookDto::title);
            };
            if (requested.isDescending()) {
                order = order.reversed();
            }
        }
        List<BookDto> all = store.values().stream().sorted(order).toList();
        int from = (int) Math.min(pageable.getOffset(), all.size());
        int to = Math.min(from + pageable.getPageSize(), all.size());
        return new PageImpl<>(all.subList(from, to), pageable, all.size());
    }

    public BookDto find(long id) {
        BookDto book = store.get(id);
        if (book == null) {
            throw new BookNotFoundException(id);
        }
        return book;
    }

    public BookDto create(BookDto.CreateRequest request) {
        long id = ids.incrementAndGet();
        BookDto book = new BookDto(id, request.title(), request.author(), request.year(), 1);
        store.put(id, book);
        return book;
    }
}

