@Configuration
public class WebConfig implements WebMvcConfigurer {

    private static final Logger log = LoggerFactory.getLogger(WebConfig.class);

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(new HandlerInterceptor() {
            @Override
            public boolean preHandle(HttpServletRequest req, HttpServletResponse res,
                                     Object handler) {
                req.setAttribute("startNanos", System.nanoTime());
                return true;
            }

            @Override
            public void afterCompletion(HttpServletRequest req, HttpServletResponse res,
                                        Object handler, Exception ex) {
                long ms = (System.nanoTime() - (Long) req.getAttribute("startNanos")) / 1_000_000;
                log.info("{} {} -> {} in {} ms", req.getMethod(), req.getRequestURI(),
                        res.getStatus(), ms);
            }
        }).addPathPatterns("/api/**");
    }

    @Override
    public void addCorsMappings(CorsRegistry registry) {
        registry.addMapping("/api/**")
                .allowedOrigins("https://app.library.example.com")
                .allowedMethods("GET", "POST", "PUT", "DELETE")
                .allowedHeaders("Authorization", "Content-Type", "If-None-Match")
                .exposedHeaders("ETag", "Location", "X-Request-Id")
                .maxAge(3600);
    }
}

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

public class MiniDispatcher {

    record Request(String method, String path, Map<String, String> params) {}
    record Response(int status, String body) {}

    // ---- servlet filter chain ------------------------------------------------
    interface Filter { Response doFilter(Request req, Chain chain); }
    interface Chain { Response next(Request req); }

    static Chain chainOf(List<Filter> filters, Function<Request, Response> servlet) {
        return new Chain() {
            int index = 0;
            public Response next(Request req) {
                return index < filters.size()
                    ? filters.get(index++).doFilter(req, this) : servlet.apply(req);
            }
        };
    }

    // ---- handler interceptors and exception resolution ------------------------
    interface Interceptor {
        boolean preHandle(Request r);
        void postHandle(Request r, Response resp);
        void afterCompletion(Request r, Exception ex);
    }

    record Handler(String name, Function<Request, String> body) {}

    static class Dispatcher implements Function<Request, Response> {
        final Map<String, Handler> mappings = new LinkedHashMap<>();
        final List<Interceptor> interceptors = new ArrayList<>();

        public Response apply(Request req) {                       // doDispatch
            Handler h = mappings.get(req.method() + " " + req.path());
            if (h == null) return new Response(404, "no handler");
            int applied = 0;
            Exception failure = null;
            Response resp = null;
            try {
                for (Interceptor i : interceptors) {
                    if (!i.preHandle(req)) {
                        triggerAfter(req, applied, null);
                        return new Response(403, "blocked");
                    }
                    applied++;
                }
                resp = new Response(200, h.body().apply(req));
                for (int i = interceptors.size() - 1; i >= 0; i--) {
                    interceptors.get(i).postHandle(req, resp);
                }
            } catch (Exception ex) {                               // HandlerExceptionResolver
                failure = ex;
                int status = ex instanceof IllegalArgumentException ? 400 : 500;
                resp = new Response(status, ex.getMessage());
            }
            triggerAfter(req, applied, failure);
            return resp;
        }

        void triggerAfter(Request req, int applied, Exception ex) {
            for (int i = applied - 1; i >= 0; i--) interceptors.get(i).afterCompletion(req, ex);
        }
    }

    static Interceptor named(String n, boolean allow) {
        return new Interceptor() {
            public boolean preHandle(Request r) {
                System.out.println("    " + n + ".preHandle -> " + allow);
                return allow;
            }
            public void postHandle(Request r, Response x) {
                System.out.println("    " + n + ".postHandle");
            }
            public void afterCompletion(Request r, Exception e) {
                String msg = e == null ? null : e.getMessage();
                System.out.println("    " + n + ".afterCompletion ex=" + msg);
            }
        };
    }

    static Filter named(String n) {
        return (req, chain) -> {
            System.out.println("  " + n + " before");
            Response r = chain.next(req);
            System.out.println("  " + n + " after  (status " + r.status() + ")");
            return r;
        };
    }

    public static void main(String[] args) {
        Dispatcher d = new Dispatcher();
        d.mappings.put("GET /books",
            new Handler("BookController#list", r -> "[book1, book2]"));
        d.mappings.put("GET /boom", new Handler("BookController#boom", r -> {
            throw new IllegalArgumentException("page must be >= 0"); }));
        d.interceptors.add(named("A", true));
        d.interceptors.add(named("B", true));
        List<Filter> filters = List.of(named("CharacterEncodingFilter"), named("SecurityFilter"));

        for (String path : List.of("/books", "/boom", "/missing")) {
            System.out.println("GET " + path);
            Response r = chainOf(filters, d).next(new Request("GET", path, Map.of()));
            System.out.println("  => " + r);
        }

        System.out.println("GET /books with interceptor B rejecting");
        d.interceptors.set(1, named("B", false));
        Request again = new Request("GET", "/books", Map.of());
        System.out.println("  => " + chainOf(filters, d).next(again));
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;

public class PoolStarvation {

    static final int REQUESTS = 100;
    static final int BLOCKING_MS = 200;

    /** A handler that blocks on a downstream call; returns queueing delay plus service time. */
    static long handle(long submittedNanos) throws InterruptedException {
        Thread.sleep(BLOCKING_MS);
        return (System.nanoTime() - submittedNanos) / 1_000_000;
    }

    static void run(String label, ExecutorService pool) throws Exception {
        long t0 = System.nanoTime();
        List<Future<Long>> results = new ArrayList<>();
        for (int i = 0; i < REQUESTS; i++) {
            long submitted = System.nanoTime();
            results.add(pool.submit(() -> handle(submitted)));
        }
        long worst = 0;
        long sum = 0;
        for (Future<Long> f : results) {
            long ms = f.get();
            worst = Math.max(worst, ms);
            sum += ms;
        }
        long total = (System.nanoTime() - t0) / 1_000_000;
        pool.shutdown();
        System.out.printf("%-34s total=%5d ms  mean latency=%4d ms  worst=%4d ms%n",
            label, total, sum / REQUESTS, worst);
    }

    public static void main(String[] args) throws Exception {
        System.out.println(REQUESTS + " requests, each blocks " + BLOCKING_MS + " ms");
        run("platform pool, 10 threads", Executors.newFixedThreadPool(10));
        run("platform pool, 50 threads", Executors.newFixedThreadPool(50));
        run("virtual thread per request", Executors.newVirtualThreadPerTaskExecutor());
    }
}

