import com.sun.net.httpserver.HttpServer;
import java.io.IOException;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.net.http.HttpTimeoutException;
import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.Semaphore;
import java.util.concurrent.TimeUnit;

public class ClientTimeouts {

    static final int SERVER_DELAY_MS = 2000;

    static long since(long t0) { return (System.nanoTime() - t0) / 1_000_000; }

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress("127.0.0.1", 0), 0);
        server.setExecutor(Executors.newVirtualThreadPerTaskExecutor());
        server.createContext("/slow", ex -> {
            try {
                Thread.sleep(SERVER_DELAY_MS);
            } catch (InterruptedException ignored) {
                // the server is being stopped
            }
            byte[] body = "done".getBytes();
            ex.sendResponseHeaders(200, body.length);
            ex.getResponseBody().write(body);
            ex.close();
        });
        server.start();
        URI uri = URI.create("http://127.0.0.1:" + server.getAddress().getPort() + "/slow");
        HttpClient client = HttpClient.newBuilder().connectTimeout(Duration.ofMillis(500)).build();

        // 1. Without a request timeout the caller waits for the full server delay.
        long t0 = System.nanoTime();
        HttpResponse<String> r = client.send(HttpRequest.newBuilder(uri).build(),
            HttpResponse.BodyHandlers.ofString());
        System.out.printf("no request timeout : status %d after %d ms%n",
            r.statusCode(), since(t0));

        // 2. With a request timeout the call fails fast and the thread is released.
        t0 = System.nanoTime();
        try {
            client.send(HttpRequest.newBuilder(uri).timeout(Duration.ofMillis(500)).build(),
                HttpResponse.BodyHandlers.ofString());
        } catch (HttpTimeoutException e) {
            System.out.printf("request timeout   : %s after %d ms%n",
                e.getClass().getSimpleName(), since(t0));
        }

        // 3. Model of a bounded connection pool: 2 connections, 6 callers, lease timeout 1 s.
        Semaphore pool = new Semaphore(2);
        ExecutorService callers = Executors.newFixedThreadPool(6);
        long start = System.nanoTime();
        List<Future<String>> results = new ArrayList<>();
        for (int i = 1; i <= 6; i++) {
            final int id = i;
            results.add(callers.submit(() -> {
                if (!pool.tryAcquire(1, TimeUnit.SECONDS)) {
                    return "caller " + id + ": lease timeout after " + since(start) + " ms";
                }
                try {
                    client.send(HttpRequest.newBuilder(uri).build(),
                        HttpResponse.BodyHandlers.ofString());
                    return "caller " + id + ": ok after " + since(start) + " ms";
                } finally {
                    pool.release();
                }
            }));
        }
        List<String> lines = new ArrayList<>();
        for (Future<String> f : results) lines.add(f.get());
        lines.stream().sorted().forEach(System.out::println);
        callers.shutdown();
        server.stop(0);
    }
}

