        } catch (HttpClientErrorException.NotFound e) {
            return Optional.empty();                         // 404: no such price, not an outage
        } catch (HttpServerErrorException | ResourceAccessException e) {
            log.warn("pricing unavailable for {}: {}", isbn, e.toString());
            throw new PricingUnavailableException(isbn, e);  // mapped to 503 by a handler
        }
    }
}

